{
  "contract": "AmenoToken",
  "closure": {
    "site_function": "swapAndSendMarketingFee",
    "site_call": ".call",
    "functions": [
      "swapAndSendMarketingFee",
      "claimMarketingFees",
      "swapOnDemand",
      "deflationaryBurn"
    ],
    "justification": "These functions interact with the pendingMarketingFee and pendingBurnFee, which are exposed during the callback."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "claimMarketingFees",
      "swapOnDemand",
      "deflationaryBurn"
    ],
    "nesting_bound": {
      "claimMarketingFees": 1,
      "swapOnDemand": 1,
      "deflationaryBurn": 1
    }
  },
  "phases": {
    "function": "swapAndSendMarketingFee",
    "pre": {
      "name": "pre",
      "from_marker": "start",
      "to_marker": "before_external_call"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "before_external_call",
      "to_marker": "after_external_call"
    },
    "post": {
      "name": "post",
      "from_marker": "after_external_call",
      "to_marker": "end"
    },
    "linearization_point": "after_external_call"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "Amount of marketing fees in-flight during the callback window",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "pendingMarketingFee + pendingBurnFee + inFlight <= _balances[address(this)]",
    "stable_formula": "pendingMarketingFee + pendingBurnFee <= _balances[address(this)]",
    "kind": "additive"
  },
  "composition": {
    "target_property": "pendingMarketingFee + pendingBurnFee <= _balances[address(this)]",
    "rule": "The exposure invariant ensures that the sum of pending fees and in-flight fees does not exceed the contract's balance."
  }
}
